1	import type { MessageStoreWrite } from "@kena/shared";
2	
3	/**
4	 * Buffer de escritura entre los handlers del gateway y el store de mensajes de
5	 * Postgres.
6	 *
7	 * MESSAGE_CREATE es el evento más caliente del gateway. Escribir una fila por
8	 * evento con una petición HTTP a api-db costaría un round-trip por mensaje y
9	 * un INSERT por mensaje: a 5.000 msg/s eso son 5.000 peticiones/s y 5.000
10	 * transacciones/s, que no aguanta ni el servicio ni la base de datos.
11	 *
12	 * Este buffer los agrupa: acumula filas en memoria y las vuelca en lotes de
13	 * hasta `maxBatchSize` cada `flushIntervalMs`. A 5.000 msg/s con los valores
14	 * por defecto son ~10 peticiones/s con 500 filas cada una, y cada lote es UNA
15	 * sentencia (`INSERT ... FROM UNNEST(...)`).
16	 *
17	 * ── Qué se pierde y por qué es aceptable ─────────────────────────────────────
18	 * El buffer vive en memoria del worker. Si el proceso muere de forma abrupta
19	 * (SIGKILL, OOM) se pierde lo acumulado desde el último flush: como mucho
20	 * `flushIntervalMs` de mensajes. En una parada ordenada no se pierde nada,
21	 * porque `shutdown()` vacía lo pendiente antes de salir. Se eligió esto frente
22	 * a un Redis Stream con consumer group porque el objetivo de todo el cambio es
23	 * QUITAR carga de Redis, y un stream la volvería a meter.
24	 *
25	 * ── Coalescencia ─────────────────────────────────────────────────────────────
26	 * Las filas se indexan por id de mensaje, no se encolan en lista. Si un mensaje
27	 * se crea y se edita dentro de la misma ventana de flush, sale una sola fila
28	 * con el estado final en vez de dos escrituras que compiten. Es además lo que
29	 * evita el error de Postgres "ON CONFLICT DO UPDATE command cannot affect row a
30	 * second time" cuando la misma clave aparece dos veces en la misma sentencia
31	 * (el repositorio tiene además su propio `DISTINCT ON` como red de seguridad).
32	 */
33	
34	export interface MessageIngestLogger {
35		debug(msg: string, meta?: Record<string, unknown>): void;
36		warn(msg: string, meta?: Record<string, unknown>): void;
37		error(msg: string, meta?: Record<string, unknown>): void;
38	}
39	
