import type { MessageStoreWrite } from "@kena/shared";

/**
 * Buffer de escritura entre los handlers del gateway y el store de mensajes de
 * Postgres.
 *
 * MESSAGE_CREATE es el evento más caliente del gateway. Escribir una fila por
 * evento con una petición HTTP a api-db costaría un round-trip por mensaje y
 * un INSERT por mensaje: a 5.000 msg/s eso son 5.000 peticiones/s y 5.000
 * transacciones/s, que no aguanta ni el servicio ni la base de datos.
 *
 * Este buffer los agrupa: acumula filas en memoria y las vuelca en lotes de
 * hasta `maxBatchSize` cada `flushIntervalMs`. A 5.000 msg/s con los valores
 * por defecto son ~10 peticiones/s con 500 filas cada una, y cada lote es UNA
 * sentencia (`INSERT ... FROM UNNEST(...)`).
 *
 * ── Qué se pierde y por qué es aceptable ─────────────────────────────────────
 * El buffer vive en memoria del worker. Si el proceso muere de forma abrupta
 * (SIGKILL, OOM) se pierde lo acumulado desde el último flush: como mucho
 * `flushIntervalMs` de mensajes. En una parada ordenada no se pierde nada,
 * porque `shutdown()` vacía lo pendiente antes de salir. Se eligió esto frente
 * a un Redis Stream con consumer group porque el objetivo de todo el cambio es
 * QUITAR carga de Redis, y un stream la volvería a meter.
 *
 * ── Coalescencia ─────────────────────────────────────────────────────────────
 * Las filas se indexan por id de mensaje, no se encolan en lista. Si un mensaje
 * se crea y se edita dentro de la misma ventana de flush, sale una sola fila
 * con el estado final en vez de dos escrituras que compiten. Es además lo que
 * evita el error de Postgres "ON CONFLICT DO UPDATE command cannot affect row a
 * second time" cuando la misma clave aparece dos veces en la misma sentencia
 * (el repositorio tiene además su propio `DISTINCT ON` como red de seguridad).
 */

export interface MessageIngestLogger {
	debug(msg: string, meta?: Record<string, unknown>): void;
	warn(msg: string, meta?: Record<string, unknown>): void;
	error(msg: string, meta?: Record<string, unknown>): void;
}

export interface MessageIngestTransport {
	/**
	 * Escribe un lote. Debe resolver a `false` si el destino lo rechazó ENTERO.
	 *
	 * El número que devuelve, cuando lo devuelve, es cuántas filas rechazó el
	 * servidor una a una habiendo escrito el resto: eso NO es un fallo del lote,
	 * solo se contabiliza.
	 */
	writeBatch(rows: MessageStoreWrite[]): Promise<boolean | { ok: boolean; rejected?: number }>;
	/** Marca ids como borrados. Debe resolver a `false` si el destino lo rechazó. */
	markDeleted(ids: string[]): Promise<boolean | { ok: boolean; rejected?: number }>;
}

export interface MessageIngestBufferOptions {
	/** Master switch. Con `false` el buffer acepta y descarta: nada llega a Postgres. */
	enabled?: boolean;
	/** Cada cuánto se vuelca lo acumulado. Por defecto 500 ms. */
	flushIntervalMs?: number;
	/** Filas por petición. Por defecto 500 (el servidor acepta hasta 1.000). */
	maxBatchSize?: number;
	/**
	 * Tope de BYTES serializados por petición. Por defecto 3 MiB.
	 *
	 * El tope por número de filas no basta: api-db-go corre sobre Fiber, cuyo
	 * `BodyLimit` acota el cuerpo de la petición, y 500 mensajes ricos (embeds
	 * llenos, 10 adjuntos) se van a ~18 MiB. El servidor contestaba 413, el
	 * reintento fallaba igual y el lote ENTERO se descartaba — 500 mensajes
	 * perdidos, en silencio salvo por un log de error.
	 *
	 * 3 MiB deja margen holgado bajo el límite del servidor para cabeceras y para
	 * la diferencia entre esta estimación y el JSON final.
	 */
	maxBatchBytes?: number;
	/**
	 * Tope duro de filas en memoria. Si api-db está caído, sin este tope el
	 * buffer crecería hasta agotar el heap del worker y tumbar el bot por un
	 * fallo de un servicio auxiliar. Al llegar al tope se descartan las filas
	 * NUEVAS y se cuentan en `droppedMessages`. Por defecto 20.000 filas
	 * (~40 s de margen a 500 msg/s).
	 */
	maxBufferedMessages?: number;
	/** Mismo tope para los ids pendientes de marcar como borrados. */
	maxBufferedDeletes?: number;
}

// `type` y no `interface` a propósito: los alias de tipo obtienen firma de
// índice implícita, así que un `MessageIngestStats` se puede pasar donde se
// espera `Record<string, unknown>` — que es exactamente lo que pide el `meta`
// del logger. Una interface no lo permitiría.
export type MessageIngestStats = {
	/** Filas aceptadas por el buffer desde el arranque. */
	enqueued: number;
	/** Filas confirmadas por api-db. */
	flushed: number;
	/** Filas descartadas por tope de buffer o por fallo tras reintento. */
	droppedMessages: number;
	/** Ids de borrado descartados por tope de buffer o por fallo tras reintento. */
	droppedDeletes: number;
	/** Lotes que fallaron (incluye los que luego el reintento salvó). */
	failedBatches: number;
	/** Filas esperando ahora mismo. */
	pendingMessages: number;
	/** Ids de borrado esperando ahora mismo. */
	pendingDeletes: number;
	/** Filas que el servidor rechazó una a una sin tumbar su lote. */
	rejectedMessages: number;
	/** Filas descartadas aquí por no caber ellas solas en `maxBatchBytes`. */
	oversizedMessages: number;
};

const DEFAULTS = {
	enabled: true,
	flushIntervalMs: 500,
	maxBatchSize: 500,
	maxBatchBytes: 3 * 1024 * 1024,
	maxBufferedMessages: 20_000,
	maxBufferedDeletes: 20_000
} as const;

export class MessageIngestBuffer {
	private readonly transport: MessageIngestTransport;
	private readonly logger: MessageIngestLogger;
	private readonly options: Required<MessageIngestBufferOptions>;

	/** Map en vez de array: coalesce por id y conserva el orden de inserción. */
	private readonly pending = new Map<string, MessageStoreWrite>();
	private readonly pendingDeletes = new Set<string>();

	private timer: NodeJS.Timeout | null = null;
	private flushing = false;
	private stopped = false;

