// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * Auditoría 2026-08-11 — `pendingRequests` sin `maxPending`.
 *
 * Cada entrada de `pendingRequests` retiene sus closures resolve/reject, un
 * `Timeout` y el payload completo de la petición mientras se espera al
 * worker. Sin un techo, si las peticiones entran más rápido de lo que el
 * worker resuelve, el Map crece hasta agotar el heap — es lo que mejor
 * explica los 10 GB de RAM del incidente del 11-08-2026.
 *
 * Estos tests fijan el contrato: al llegar al tope, la petición NUEVA se
 * rechaza de inmediato (sin entrar al Map) en vez de encolarse sin límite.
 */
describe("RequestTracker — maxPending", () => {
	let tracker: InstanceType<typeof RequestTracker>;

	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects a new request once the tracker is at capacity, without growing pendingRequests", async () => {
		tracker = new RequestTracker(30000, 2);

		const p1 = tracker.trackRequest("trace-1");
		const p2 = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/at capacity/);
		// The rejected request never entered the map — capacity stays at 2,
		// not 3.
		expect(tracker.getPendingCount()).toBe(2);

		// The two requests that were admitted are unaffected.
		tracker.resolveRequest("trace-1", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as MessageResponseIPC);
		await expect(p1).resolves.toMatchObject({ success: true });
		tracker.rejectRequest("trace-2", new Error("boom"));
		await expect(p2).rejects.toThrow("boom");
	});

	it("admits a new request again once capacity frees up", async () => {
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/at capacity/);

		tracker.resolveRequest("trace-1", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as MessageResponseIPC);
		await p1;

		const p3 = tracker.trackRequest("trace-3");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.resolveRequest("trace-3", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-3"
		} as MessageResponseIPC);
		await expect(p3).resolves.toMatchObject({ success: true });
	});

	it("a trace_id collision still supersedes the prior entry even when the tracker is full", async () => {
		tracker = new RequestTracker(30000, 1);

		const p1 = tracker.trackRequest("trace-1");
		const p2 = tracker.trackRequest("trace-1");

		await expect(p1).rejects.toThrow(/superseded/);
		expect(tracker.getPendingCount()).toBe(1);

		tracker.resolveRequest("trace-1", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as MessageResponseIPC);
		await expect(p2).resolves.toMatchObject({ success: true });
	});
});

